<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from "vue";
import { watchMarketCheckpoints } from "./marketSchedule";
import { Activity, ArrowUpRight, Search, Star, RefreshCw, ChevronRight, BarChart3 } from "@lucide/vue";

interface Stock { symbol: string; name: string; price?: number | null; change_percent?: number | null; change?: number | null; amount?: number | null; volume?: number | null; high?: number | null; low?: number | null; open?: number | null; previous_close?: number | null; close?: number | null; quote_date?: string; kind?: string }
interface Day { date: string; open: number; close: number | null }
interface ResponseData { status: string; stale: boolean; error: string; fetched_at: string | null; source: string; rows: Day[]; adjust?: string; quote_date?: string }
const tradingStatus=ref<{open:boolean;reason:string}|null>(null);
let tradingTimer:ReturnType<typeof setTimeout>|undefined;
async function loadTradingStatus(){
 clearTimeout(tradingTimer);
 try{const response=await fetch('/api/securities/trading-status');if(!response.ok)throw new Error('Unavailable');const current=await response.json();tradingStatus.value=current;if(current.next_change){const delay=Math.max(1000,Math.min(86400000,new Date(current.next_change).getTime()-new Date(current.server_time).getTime()+300));tradingTimer=setTimeout(()=>void loadTradingStatus(),delay);}}
 catch{tradingStatus.value=null;}
}
const catalog = ref<Stock[]>([]);
const quotes = ref<Stock[]>([]);
const query = ref("");
const selected = ref("000001");
const history = ref<ResponseData | null>(null);
const loading = ref(false);
const quoteLoading = ref(false);
const error = ref("");
const quoteError = ref("");
const quoteFetched = ref("");
const quoteStale = ref(false);
const tab = ref("精选");
const range = ref(120);
const adjust = ref("none");
const pointer = ref<number | null>(null);
const favorites = ref<string[]>([]);
interface Connection { user_id?: string; authenticated?: boolean; phone_masked?: string; bank_label?: string; connected: boolean; label: string; watchlist: {symbol: string; name: string}[] }
interface Portfolio { positions: {symbol:string;name:string;shares:number;cost_minor:number;price_minor?:number|null;market_value_minor?:number|null;profit_minor?:number|null;profit_percent?:number|null;quote_date?:string|null;source?:string|null}[]; orders: {id:string;side?:string;amount_minor:number;created_at:string;items:{symbol:string;name:string;shares:number}[]}[]; cost_minor?:number;market_value_minor?:number|null;profit_minor?:number|null;profit_percent?:number|null;realized_profit_minor?:number;complete?:boolean;valuation?:string }
const accountOpen=ref(false);const accountLoading=ref(false);
const amountText=(value:number|null|undefined)=>value==null?'—':(value/100).toFixed(2);
const profitText=(value:number|null|undefined)=>value==null?'—':`${value>0?'+':''}${(value/100).toFixed(2)}`;

const connection = ref<Connection>({connected:false,label:"",watchlist:[]});
const connectionOpen = ref(false);
const connectBusy = ref(false);
const connectionError = ref("");
const loginOpen = ref(false); const loginPhone = ref(""); const loginCode = ref(""); const loginError = ref(""); const loginBusy = ref(false); const smsNotice = ref<{code:string;phone:string}|null>(null);
const pairingCode = ref("");
const portfolio = ref<Portfolio | null>(null);
const portfolioError = ref("");
const watchBusy = ref(false);
async function securitiesApi<T>(path: string, body?: unknown, method = "POST"): Promise<T> {
  const headers: Record<string,string> = {}; if(body!==undefined)headers['Content-Type']='application/json';if(connection.value.user_id && path!='/session' && !path.startsWith('/auth/'))headers['x-stock-account']=connection.value.user_id;
  const response = await fetch('/api/securities'+path,{method:body===undefined?'GET':method,credentials:'same-origin',headers,body:body===undefined?undefined:JSON.stringify(body)});
  const value = await response.json();
  if (!response.ok) {if(response.status===401){connection.value={connected:false,label:'',watchlist:[]};favorites.value=[];portfolio.value=null;connectionOpen.value=false;loginOpen.value=true;}throw new Error(typeof value.detail==='string'?value.detail:'证券请求未完成');}
  return value;
}
async function loadPortfolio() {
  portfolioError.value = '';
  if (!connection.value.connected || accountLoading.value) return;
  const account=connection.value.user_id;accountLoading.value=true;
  try { const result=await securitiesApi<Portfolio>('/account');if(account===connection.value.user_id)portfolio.value=result; }
  catch(e) { if(account===connection.value.user_id)portfolioError.value=(e as Error).message; }finally{accountLoading.value=false;}
}
async function sendLoginSms() {
  loginBusy.value=true;loginError.value="";
  try {const r=await securitiesApi<{demo_code:string;phone_masked:string}>("/auth/sms",{phone:loginPhone.value.trim()});smsNotice.value={code:r.demo_code,phone:r.phone_masked};}catch(e){loginError.value=(e as Error).message;}finally{loginBusy.value=false;}
}
async function login() {
  loginBusy.value=true;loginError.value="";
  try{await securitiesApi("/auth/login",{phone:loginPhone.value.trim(),code:loginCode.value.trim()});connection.value=await securitiesApi<Connection>("/session");favorites.value=connection.value.watchlist.map(s=>s.symbol);portfolio.value=null;portfolioError.value="";loginCode.value="";smsNotice.value=null;loginOpen.value=false;if(connection.value.connected)await loadPortfolio();}catch(e){loginError.value=(e as Error).message;}finally{loginBusy.value=false;}
}
async function connectAccount() {
  if(connectBusy.value) return;
  connectBusy.value=true;connectionError.value='';
  try { connection.value=await securitiesApi<Connection>('/connect',{symbols:[],code:pairingCode.value.trim()});favorites.value=connection.value.watchlist.map(s=>s.symbol);connectionOpen.value=false;pairingCode.value="";await loadPortfolio(); }
  catch(e){connectionError.value=(e as Error).message;}
  finally{connectBusy.value=false;}
}
async function disconnectAccount() {
  if(connectBusy.value) return;
  connectBusy.value=true;connectionError.value='';
  try {await securitiesApi('/auth/logout',{});connection.value={connected:false,label:'',watchlist:[]};portfolio.value=null;favorites.value=[];connectionOpen.value=false;pairingCode.value="";loginPhone.value="";loginCode.value="";smsNotice.value=null;}
  catch(e){connectionError.value=(e as Error).message;}
  finally{connectBusy.value=false;}
}
let historyRequest = 0;
let clockTimer: ReturnType<typeof setInterval> | undefined;
const clock = ref(new Date().toLocaleString("zh-CN", { timeZone: "Asia/Shanghai", hour12: false }));
async function api<T>(path: string): Promise<T> {
  const r = await fetch('/api/stocks' + path);
  if (!r.ok) throw new Error(`行情服务请求失败（${r.status}）`);
  return r.json();
}
const fmt = (n: number | null | undefined, digits = 2) => n == null || !Number.isFinite(n) ? '—' : n.toFixed(digits);
const pct = (n: number | null | undefined) => n == null ? '—' : `${n > 0 ? '+' : ''}${n.toFixed(2)}%`;
const color = (n: number | null | undefined) => n == null || n === 0 ? '' : n > 0 ? 'up' : 'down';
const merged = computed(() => {
  const result = new Map<string, Stock>(catalog.value.map(s => [s.symbol, s]));
  for (const item of quotes.value) result.set(item.symbol, item);
  const latest = history.value?.rows.at(-1);
  if (latest && !result.get(selected.value)?.price) {
    result.set(selected.value, { ...(result.get(selected.value) || { symbol: selected.value, name: selected.value }), price: latest.close ?? latest.open, open: latest.open, close: latest.close, quote_date: latest.date, kind: latest.close == null ? '开盘价' : '收盘价' });
  }
  return result;
});
const stock = computed(() => merged.value.get(selected.value) || {symbol:selected.value, name:selected.value});
const list = computed(() => [...merged.value.values()].filter(s => (tab.value !== '自选' || favorites.value.includes(s.symbol)) && (!query.value.trim() || s.symbol.includes(query.value.trim()) || s.name.includes(query.value.trim()))).slice(0, 120));
const daily = computed(() => history.value?.rows || []);
const inspected = computed(() => daily.value[pointer.value ?? daily.value.length - 1]);
const min = computed(() => daily.value.length ? Math.min(...daily.value.flatMap(d => d.close == null ? [d.open] : [d.open,d.close])) : 0);
const max = computed(() => daily.value.length ? Math.max(...daily.value.flatMap(d => d.close == null ? [d.open] : [d.open,d.close])) : 1);
const padding = computed(() => Math.max((max.value - min.value) * .08, max.value * .004));
const bottom = computed(() => min.value - padding.value);
const top = computed(() => max.value + padding.value);
const y = (price: number) => 22 + (top.value - price) / Math.max(.001, top.value - bottom.value) * 270;
const x = (index: number) => 58 + (index + .5) * 830 / Math.max(1, daily.value.length);
const openLine = computed(() => daily.value.map((d,i) => `${x(i)},${y(d.open)}`).join(' '));
const closeLine = computed(() => daily.value.map((d,i) => d.close == null ? '' : `${x(i)},${y(d.close)}`).filter(Boolean).join(' '));
function move(event: MouseEvent) { const box = (event.currentTarget as SVGSVGElement).getBoundingClientRect(); const n = Math.floor(((event.clientX-box.left)/box.width*920-58)/830*daily.value.length); pointer.value = Math.max(0,Math.min(n,daily.value.length-1)); }
async function toggleFavorite(code: string) {
  if(!connection.value.authenticated){loginOpen.value=true;return;}
  if(watchBusy.value) return;
  const previous=[...favorites.value];
  const next=favorites.value.includes(code)?favorites.value.filter(v=>v!==code):[...favorites.value,code];
  if(next.length>20){connectionError.value='自选最多20只股票。';connectionOpen.value=true;return;}
  favorites.value=next;watchBusy.value=true;
  try{
    if(connection.value.authenticated){const result=await securitiesApi<{watchlist:{symbol:string;name:string}[]}>('/watchlist',{symbols:next},'PUT');connection.value.watchlist=result.watchlist;}

  }catch(e){favorites.value=previous;connectionError.value=(e as Error).message;connectionOpen.value=true;}
  finally{watchBusy.value=false;}
}
async function loadHistory() {
  const request = ++historyRequest; loading.value = true; error.value = ''; history.value = null; pointer.value = null;
  try { const result = await api<ResponseData>(`/${selected.value}/history?days=${range.value}&adjust=${adjust.value}`); if (request !== historyRequest) return; history.value = result; error.value = result.error || ''; }
  catch (e) { if (request === historyRequest) error.value = (e as Error).message; }
  finally { if (request === historyRequest) loading.value = false; }
}
function choose(code: string) { if (code === selected.value && history.value) return; selected.value = code; void loadHistory(); }
function searchCode() { const code=query.value.trim(); if (/^\d{6}$/.test(code)) { if(catalog.value.some(s=>s.symbol===code)) choose(code); else error.value="测试版本仅支持股票池中的20只股票。"; } }
async function loadQuotes() {
  if (quoteLoading.value) return;
  quoteLoading.value = true; quoteError.value = '';
  try { const result = await api<{rows: Stock[]; error: string; fetched_at: string; stale: boolean; pending?: boolean}>('/quotes?limit=20'); quotes.value = result.rows; quoteError.value = result.error; quoteFetched.value = result.fetched_at; quoteStale.value = result.stale; if(result.pending && initialRetries++ < 30) { clearTimeout(warmTimer); warmTimer=setTimeout(()=>void loadQuotes(),3000); } }
  catch (e) { quoteError.value = (e as Error).message; }
  finally { quoteLoading.value = false; }
}
async function refreshSession() {
  void loadTradingStatus();
  try{const next=await securitiesApi<Connection>("/session");if(next.user_id!==connection.value.user_id){portfolio.value=null;portfolioError.value="";connectionOpen.value=false;pairingCode.value="";}connection.value=next;favorites.value=next.watchlist.map(s=>s.symbol);if(next.connected)await loadPortfolio();}catch{/* Keep the current page when the service is temporarily unavailable. */}
}
async function initialize() { void loadTradingStatus(); try { connection.value=await securitiesApi<Connection>("/session");if(connection.value.authenticated){favorites.value=connection.value.watchlist.map(s=>s.symbol);if(connection.value.connected)void loadPortfolio();}else{favorites.value=[];loginOpen.value=true;} }catch(e){connectionError.value=(e as Error).message;} try { catalog.value = (await api<{items: Stock[]}>('/catalog')).items; } catch (e) { quoteError.value = (e as Error).message; } void loadHistory(); void loadQuotes(); }
let stopMarketSchedule: (() => void) | undefined;
let warmTimer: ReturnType<typeof setTimeout> | undefined;
let initialRetries = 0;
onMounted(() => {
  stopMarketSchedule=watchMarketCheckpoints(()=>{initialRetries=0;void loadQuotes();void loadHistory();if(connection.value.connected)void loadPortfolio();});
  document.title='有数证券 · 开盘与收盘';window.addEventListener('focus',refreshSession);void initialize();
  clockTimer=setInterval(()=>{clock.value=new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});},1000);
});
onUnmounted(()=>{clearTimeout(tradingTimer);stopMarketSchedule?.();clearTimeout(warmTimer);window.removeEventListener('focus',refreshSession);if(clockTimer)clearInterval(clockTimer);historyRequest++;});
</script>

<template>
  <div class="terminal">
    <header class="topbar"><a href="/" class="brand"><span class="brand-mark"><Activity :size="25" /></span><div><b>有数证券</b><small>MARKET TERMINAL</small></div></a><nav><button :class="{active:!accountOpen}" @click="accountOpen=false">行情研究</button><button @click="accountOpen=false;tab='自选'">我的自选</button><button :class="{active:accountOpen}" @click="accountOpen=true;if(connection.connected)void loadPortfolio()">我的账户</button></nav><button v-if="connection.authenticated" class="connect-account" @click="connectionOpen=true;connectionError=''">{{ connection.phone_masked }} · {{ connection.connected ? '已关联' : '关联有数' }}</button><button v-else class="connect-account" @click="loginOpen=true">手机号登录</button><div class="top-status"><span class="live-dot"></span>AKShare 数据接入<span class="clock">{{ clock }}</span></div></header>
    <div class="notice"><span class="outlined-label">研究演示</span>开盘价 / 收盘价 · 交易日09:30–11:30、13:00–15:00可模拟买卖<span>{{tradingStatus?.reason || "交易状态以后台校验为准"}} · 无实盘交易</span></div>
    <main v-if="!accountOpen" class="workspace">
      <aside class="stock-browser"><div class="browser-title"><h2>市场观察</h2><span>20只测试股票</span></div><form class="search" @submit.prevent="searchCode"><Search :size="16" /><input v-model="query" placeholder="股票名称 / 六位代码" aria-label="搜索股票" /><button v-if="/^\d{6}$/.test(query.trim())" aria-label="查询股票代码" type="submit"><ChevronRight :size="16" /></button></form><div class="list-tabs"><button v-for="name in ['精选','自选','股票池']" :key="name" :class="{active:tab===name}" @click="tab=name">{{ name }}</button><button class="refresh-icon" :disabled="quoteLoading" aria-label="刷新行情列表" @click="loadQuotes"><RefreshCw :size="13" :class="{spinning:quoteLoading}" /></button></div><div class="list-caption"><span>名称 / 代码</span><span>开盘 / 收盘</span></div><div class="stock-list"><button v-for="item in list.filter(s=>tab!=='精选'||catalog.some(c=>c.symbol===s.symbol)||s.symbol===selected)" :key="item.symbol" class="stock-row" :class="{selected:item.symbol===selected}" @click="choose(item.symbol)"><div><b>{{ item.name }}</b><small>{{ item.symbol.startsWith('6') ? 'SH' : item.symbol.startsWith('8') || item.symbol.startsWith('4') || item.symbol.startsWith('9') ? 'BJ' : 'SZ' }} {{ item.symbol }}<span v-if="item.quote_date"> · {{item.quote_date}}</span></small></div><div class="daily-price-pair"><b>开 {{ fmt(item.open) }}</b><small>收 {{ item.close == null ? (item.open != null ? '待收盘' : '—') : fmt(item.close) }}</small></div></button><p v-if="!list.length" class="empty">没有匹配项。测试版本仅支持股票池中的20只股票。</p></div><div class="browser-foot"><span v-if="quoteLoading">正在获取行情列表…</span><span v-else-if="quoteError">{{ quoteError }} 可单独查询股票历史。</span><span v-else>{{ quotes.length }} 只股票 · {{ quoteStale ? '最近可用数据' : '开盘 / 收盘' }}</span><small v-if="quoteFetched">获取于 {{ new Date(quoteFetched).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai'}) }}</small></div></aside>
      <section class="main-market"><div class="instrument"><div><div class="breadcrumb">市场行情 <ChevronRight :size="12" />A股 <ChevronRight :size="12" />{{ selected }}</div><div class="instrument-title"><h1>{{ stock.name }}</h1><span>{{ selected }}</span><button class="favorite" :class="{saved:favorites.includes(selected)}" @click="toggleFavorite(selected)"><Star :size="15" :fill="favorites.includes(selected)?'currentColor':'none'" />{{ favorites.includes(selected)?'已自选':'加自选' }}</button></div></div><div class="quote-price" :class="color(stock.change_percent)"><strong>{{ fmt(stock.price) }}</strong><span>{{ pct(stock.change_percent) }}</span><small>{{ stock.quote_date }} · {{ stock.kind || '等待开收盘数据' }}</small></div></div>
        <div class="instrument-metrics"><div><span>开盘价</span><b>{{ fmt(stock.open) }}</b></div><div><span>收盘价</span><b>{{stock.close == null ? (stock.open != null ? '待收盘' : '—') : fmt(stock.close)}}</b></div><div><span>行情日期</span><b>{{stock.quote_date || '—'}}</b></div></div>
        <section class="chart-panel"><div class="chart-toolbar"><div class="chart-tabs"><button class="active">开盘 / 收盘走势</button></div><div class="chart-options"><select v-model="range" aria-label="历史范围" @change="loadHistory"><option :value="30">近30交易日</option><option :value="120">近120交易日</option><option :value="240">近240交易日</option></select><select v-model="adjust" aria-label="复权方式" @change="loadHistory"><option value="none">不复权</option><option value="qfq">前复权</option></select><button :disabled="loading" aria-label="刷新当前股票" @click="loadHistory"><RefreshCw :size="14" :class="{spinning:loading}" /></button></div></div>
          <div class="chart-meta"><span class="ma5">开盘价</span><span class="ma10">收盘价</span><span class="chart-date" v-if="inspected">{{inspected.date}}　开 {{fmt(inspected.open)}}　收 {{inspected.close == null ? '待收盘' : fmt(inspected.close)}}</span></div>
          <div v-if="loading" class="chart-empty"><div class="loading-rings"></div><h3>正在连接行情源</h3><p>获取 {{ selected }} 历史数据，首次查询可能需要数十秒</p></div>
          <div v-else-if="!daily.length" class="chart-empty"><BarChart3 :size="44" /><h3>暂时没有可用行情</h3><p>{{ error || '请选择一只股票查询' }}</p><button @click="loadHistory">重新获取 <ArrowUpRight :size="14" /></button></div>
          <template v-else><p v-if="history?.stale" class="stale-warning">{{ error }} 当前展示上次成功获取的数据。</p><svg class="price-chart" viewBox="0 0 920 410" role="img" aria-label="股票开盘与收盘价格图" @mousemove="move" @mouseleave="pointer=null"><title>{{ stock.name }} {{ adjust==='qfq'?'前复权':'不复权' }}开盘与收盘</title><g v-for="i in 5" :key="i"><line x1="58" :y1="22+(i-1)*67.5" x2="888" :y2="22+(i-1)*67.5" class="grid-line" /><text x="4" :y="26+(i-1)*67.5">{{ (top-(top-bottom)*(i-1)/4).toFixed(2) }}</text></g><polyline :points="openLine" fill="none" stroke="#e4bc72" stroke-width="2"/><polyline :points="closeLine" fill="none" stroke="#9e8bcd" stroke-width="2"/><g v-if="pointer!==null&&inspected"><line :x1="x(pointer)" :x2="x(pointer)" y1="20" y2="382" stroke="#a8b4c5" stroke-dasharray="3 4" /><circle :cx="x(pointer)" :cy="y(inspected.close ?? inspected.open)" r="3" fill="#e5bf72" /></g><text x="58" y="402">{{ daily[0]?.date }}</text><text x="888" y="402" text-anchor="end">{{ daily.at(-1)?.date }}</text></svg></template>
          <div class="chart-source"><span><span class="live-dot"></span>{{ history?.source || 'AKShare 行情服务' }}</span><span v-if="history?.fetched_at">数据截至 {{ history.quote_date }} · 获取于 {{ new Date(history.fetched_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}) }}</span></div>
        </section>
        <section class="daily-panel"><div class="section-top"><h2>每日开收盘</h2><span>人民币元 · {{adjust==='qfq'?'前复权':'不复权'}}</span></div><div class="table-scroll"><table><thead><tr><th>交易日期</th><th>开盘价</th><th>收盘价</th></tr></thead><tbody><tr v-for="d in [...daily].reverse().slice(0,30)" :key="d.date"><td>{{d.date}}</td><td>{{fmt(d.open)}}</td><td>{{d.close == null ? '待收盘' : fmt(d.close)}}</td></tr><tr v-if="!daily.length"><td colspan="3" class="empty">{{loading?'正在加载…':'暂无数据'}}</td></tr></tbody></table></div></section>
      </section>
      <aside class="research-side"><div class="section-top"><h2>观察清单</h2><Star :size="14" /></div><p class="side-caption">{{ connection.authenticated ? '自选保存在当前证券账号，按账号隔离' : '登录证券账号后保存自选' }}</p><button v-for="code in favorites" :key="code" class="watch-row" @click="choose(code)"><div><b>{{ merged.get(code)?.name || code }}</b><small>{{ code }}</small></div><span :class="color(merged.get(code)?.change_percent)">{{ pct(merged.get(code)?.change_percent) }}</span></button><div class="research-note"><span class="outlined-label">数据说明</span><h3>看见价格，也看见来源。</h3><p>20只股票统一读取开盘价、收盘价；盘中按开盘价估值，收盘后按收盘价估值。休市或接口不可用时保留最近行情。</p><p>首次加载补齐缺失数据，之后仅在工作日开盘后、收盘后更新。历史价格不代表当前可成交价。</p><a href="https://akshare.akfamily.xyz/data/stock/stock.html" target="_blank" rel="noopener">查看数据文档 <ArrowUpRight :size="13" /></a></div></aside>
    </main><main v-else class="stock-account-page"><div class="account-heading"><div><span class="outlined-label">MY ACCOUNT</span><h1>我的账户</h1><p>{{ connection.phone_masked || '尚未登录' }}<template v-if="connection.connected"> · 已关联 {{ connection.bank_label }}</template></p></div><button class="portfolio-refresh" :disabled="accountLoading || !connection.connected" @click="loadPortfolio">{{ accountLoading?'正在同步估值…':'刷新持仓与盈亏' }}</button></div>
      <section v-if="!connection.authenticated" class="account-empty"><h2>登录后查看你的账户</h2><button class="portfolio-refresh" @click="loginOpen=true">手机号登录</button></section><section v-else-if="!connection.connected" class="account-empty"><h2>当前证券账户尚未关联有数</h2><p>用有数同步码建立一对一关联，查看该账户的模拟持仓和成交。</p><button class="portfolio-refresh" @click="connectionOpen=true">关联有数账户</button></section>
      <template v-else><p v-if="portfolioError" class="portfolio-error" role="alert">{{ portfolioError }}</p><p v-if="accountLoading" class="portfolio-note" role="status">正在读取持仓和最近可用行情，首次查询可能需要数十秒。</p><div class="account-metrics"><article><span>持仓估值（元）</span><strong>{{ amountText(portfolio?.market_value_minor) }}</strong><small>买入成本 ¥{{ amountText(portfolio?.cost_minor) }}</small></article><article><span>持仓浮动盈亏（元）</span><strong :class="color(portfolio?.profit_minor)">{{ profitText(portfolio?.profit_minor) }}</strong><small :class="color(portfolio?.profit_percent)">{{ pct(portfolio?.profit_percent) }}</small></article><article><span>累计已实现盈亏（元）</span><strong :class="color(portfolio?.realized_profit_minor)">{{ profitText(portfolio?.realized_profit_minor) }}</strong><small>按模拟卖出成交计算</small></article></div><p class="portfolio-note">{{ portfolio?.valuation || '等待持仓估值数据' }}<span v-if="portfolio && !portfolio.complete"> 部分股票行情不可用，合计估值及浮动盈亏暂不计算。</span></p>
      <section class="account-positions"><h2>我的持仓</h2><p v-if="portfolio && !portfolio.positions.length" class="portfolio-note">暂无股票持仓</p><article v-for="position in portfolio?.positions||[]" :key="position.symbol" class="account-position"><div class="position-heading"><div><h3>{{ position.name }}</h3><small>{{ position.symbol }} · {{ position.shares }} 股</small></div><div class="position-profit" :class="color(position.profit_minor)"><strong>{{ profitText(position.profit_minor) }}</strong><small>{{ pct(position.profit_percent) }}</small></div></div><dl><div><dt>买入成本</dt><dd>¥{{ amountText(position.cost_minor) }}</dd></div><div><dt>平均成本价</dt><dd>¥{{ (position.cost_minor/100/position.shares).toFixed(4) }}</dd></div><div><dt>估值单价</dt><dd>{{ amountText(position.price_minor) }}</dd></div><div><dt>持仓估值</dt><dd>{{ amountText(position.market_value_minor) }}</dd></div></dl><p v-if="position.quote_date" class="portfolio-note">行情日期 {{ position.quote_date }} · {{ position.source }}</p><p v-else class="portfolio-note">行情暂不可用，保留原始持仓成本，盈亏未估值。</p></article></section>
      <section class="account-orders"><h2>成交记录</h2><p class="portfolio-note">可在有数“投资账户 → 我的理财”选择持仓卖出，确认成交后同步到此账户。</p><div v-for="order in portfolio?.orders||[]" :key="order.id" class="stock-order"><span>{{ order.created_at.slice(0,19).replace('T',' ') }} · {{ order.side==='sell'?'模拟卖出':'模拟买入' }}</span><b>{{ order.side==='sell'?'+':'−' }}¥{{ amountText(order.amount_minor) }}</b><small>{{ order.items.map(i=>i.name+' '+i.shares+'股').join('、') }} · 回执 {{ order.id.slice(-8).toUpperCase() }}</small></div><p v-if="portfolio && !portfolio.orders.length" class="portfolio-note">暂无成交记录</p></section></template>
    </main><footer>有数证券 · 独立行情研究页面<span>支持有数授权后的模拟买入，未连接真实券商交易</span></footer>
    <div v-if="loginOpen" class="stock-modal-backdrop" @click.self="loginOpen=false"><section class="stock-connect-dialog" role="dialog" aria-modal="true" aria-label="证券手机号登录"><h2>登录有数证券</h2><p>使用手机号和短信验证码登录，首次验证自动创建独立账号。演示账号：11111111111。</p><form @submit.prevent="login"><label class="pairing-code-label">手机号<input v-model="loginPhone" aria-label="证券手机号" inputmode="tel" maxlength="11" pattern="1[0-9]{10}" required autocomplete="tel" /></label><button type="button" class="portfolio-refresh" :disabled="loginBusy || !/^1[0-9]{10}$/.test(loginPhone.trim())" @click="sendLoginSms">获取短信验证码</button><label class="pairing-code-label">短信验证码<input v-model="loginCode" aria-label="证券短信验证码" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" required autocomplete="one-time-code" /></label><p v-if="loginError" role="alert" class="portfolio-error">{{ loginError }}</p><div class="stock-modal-actions"><button type="button" @click="loginOpen=false">稍后登录</button><button type="submit" class="connect-primary" :disabled="loginBusy">验证并登录</button></div></form></section></div>
    <aside v-if="smsNotice" class="stock-sms-notice" role="status"><button aria-label="关闭模拟短信" @click="smsNotice=null">×</button><b>模拟短信 · 有数证券</b><p>{{ smsNotice.phone }} 的验证码</p><strong>{{ smsNotice.code }}</strong><p>5分钟有效，仅用于演示，不发送真实短信。</p></aside>
    <div v-if="connectionOpen" class="stock-modal-backdrop" @click.self="connectionOpen=false"><section class="stock-connect-dialog" role="dialog" aria-modal="true" aria-label="连接有数账户"><h2>{{ connection.connected ? '证券连接账户' : '连接有数账户' }}</h2><p v-if="!connection.connected">在有数的“应用设置 → 证券账户同步码”生成8位同步码，在下方输入并匹配后连接。当前证券手机号 {{ connection.phone_masked }}。匹配后建立一对一关联，不会自动买入或扣款。</p><p v-else>证券账号：{{ connection.phone_masked }}，关联有数：{{ connection.bank_label }}。每个账号仅可关联一个有数账户。</p><label v-if="!connection.connected" class="pairing-code-label">8位同步码<input v-model="pairingCode" aria-label="8位同步码" type="text" inputmode="numeric" maxlength="8" autocomplete="off" placeholder="输入有数显示的同步码" /></label><p v-if="connectionError" role="alert" class="portfolio-error">{{ connectionError }}</p><div class="stock-modal-actions"><button :disabled="connectBusy" @click="connectionOpen=false">关闭</button><button :disabled="connectBusy" @click="disconnectAccount">退出证券登录</button><button v-if="!connection.connected" class="connect-primary" :disabled="connectBusy || !/^[0-9]{8}$/.test(pairingCode.trim())" @click="connectAccount">{{ connectBusy?'连接中…':'确认连接并同步' }}</button></div></section></div>
  </div>
</template>

